const assert=require('node:assert/strict')
const fs=require('node:fs')
const obra=fs.readFileSync('components/clientes/VendaKanbanObra.tsx','utf8')
const geral=fs.readFileSync('app/visao-geral-projetos/page.tsx','utf8')
for(const [nome,c] of [['Kanban da obra',obra],['Kanban Geral',geral]]){
 assert.ok(c.includes("onDragStart={e=>"),nome+': sem inicio de arraste')
 assert.ok(c.includes("e.dataTransfer.setData('text/plain','atlas-principal:'"),nome+': sem payload')
 assert.ok(c.includes("e.dataTransfer.getData('text/plain')"),nome+': drop depende incorretamente de estado React')
 assert.ok(c.includes("e.dataTransfer.dropEffect='move'"),nome+': arraste sem tipo move')
 assert.ok(c.includes('AlcaArrastarCard'),nome+': falta alça de arraste por ponteiro')
 assert.ok(c.includes('scrollLeft+='),nome+': falta rolagem horizontal')
 assert.ok(c.includes('onDragEnd='),nome+': falta limpeza de estado')
 assert.ok(c.includes('onSoltar={destino=>void mover'),nome+': arraste sem salvamento')
 assert.ok(c.includes('data-kanban-coluna'),nome+': coluna sem área identificável para o ponteiro')
}
assert.match(obra,/const id=origem.slice\('atlas-manual:'\.length\)/)
assert.match(obra,/colunas\.map\(c=><option key=\{c\.id\} value=\{c\.id\}/)
assert.match(obra,/AlcaArrastarCard desabilitado=\{salvando\}/)
assert.match(obra,/void moverPrincipal\(col\.id\)/)
assert.match(geral,/void moverCardVisual\(id,destinoVisual\)/)
assert.ok(!geral.includes('!arrastando||salvandoCard'),'Drop do Kanban Geral ainda depende do estado temporário')
const alca=fs.readFileSync('components/kanban/AlcaArrastarCard.tsx','utf8')
for(const trecho of ['setPointerCapture','hasPointerCapture','onPointerMove','onPointerUp','document.elementFromPoint','data-kanban-coluna','touchAction','onPointerCancel']){
 assert.ok(alca.includes(trecho),'Controle de ponteiro incompleto: '+trecho)
}
assert.ok(!obra.slice(obra.indexOf('async function moverPrincipal'),obra.indexOf('async function controlarProjeto')).includes('window.prompt'))
assert.ok(!geral.slice(geral.indexOf('async function moverCardVisual'),geral.indexOf('const cardAtual=useMemo')).includes('window.prompt'))
console.log('PASS: arraste por ponteiro + HTML5, seletor, salvamento direto e auditoria visual')
